from typing import Dict, List, Set, Tuple

Framework = Tuple[Set[str], Set[Tuple[str, str]]]


def attackers(af: Framework, target: str) -> Set[str]:
    return {a for (a, b) in af[1] if b == target}


def defends(af: Framework, s: Set[str], a: str) -> bool:
    for b in attackers(af, a):
        if not any((c in s and (c, b) in af[1]) for c in af[0]):
            return False
    return True


def defense_operator(af: Framework, s: Set[str]) -> Set[str]:
    return {a for a in af[0] if defends(af, s, a)}


def grounded_trace(af: Framework) -> List[Set[str]]:
    """Iterate F from the empty set until a fixed point; return every stage."""
    trace: List[Set[str]] = [set()]
    while True:
        nxt = defense_operator(af, trace[-1])
        if nxt == trace[-1]:
            return trace
        trace.append(nxt)


if __name__ == "__main__":
    af: Framework = ({"a", "b", "c"}, {("a", "b"), ("b", "c")})
    for i, s in enumerate(grounded_trace(af)):
        print(f"F^{i}(emptyset) = {sorted(s)}")
    # F^0 = [], F^1 = ['a'], F^2 = ['a', 'c'] : grounded extension {a, c}

from itertools import chain, combinations
from typing import FrozenSet, Iterable, List, Set, Tuple

Framework = Tuple[Set[str], Set[Tuple[str, str]]]


def _powerset(xs: Iterable[str]) -> Iterable[FrozenSet[str]]:
    xs = list(xs)
    return map(frozenset,
               chain.from_iterable(combinations(xs, r) for r in range(len(xs) + 1)))


def defends(af: Framework, s: Set[str], a: str) -> bool:
    for b in {x for (x, y) in af[1] if y == a}:
        if not any((c in s and (c, b) in af[1]) for c in af[0]):
            return False
    return True


def F(af: Framework, s: Set[str]) -> Set[str]:
    return {a for a in af[0] if defends(af, s, a)}


def conflict_free(af: Framework, s: Set[str]) -> bool:
    return not any((a in s and b in s) for (a, b) in af[1])


def complete(af: Framework, s: Set[str]) -> bool:
    return conflict_free(af, s) and F(af, s) == s


def grounded(af: Framework) -> Set[str]:
    cur: Set[str] = set()
    while F(af, cur) != cur:
        cur = F(af, cur)
    return cur


def complete_extensions(af: Framework) -> List[FrozenSet[str]]:
    return [s for s in _powerset(af[0]) if complete(af, set(s))]


if __name__ == "__main__":
    af: Framework = ({"a", "b"}, {("a", "b"), ("b", "a")})  # 2-cycle
    g = grounded(af)
    comps = complete_extensions(af)
    print("grounded:", sorted(g))
    print("complete extensions:", [sorted(c) for c in comps])
    assert all(g <= set(c) for c in comps)  # grounded is below every complete one
    print("verified: grounded is the least complete extension")

