from typing import Iterable, Set, Tuple

Framework = Tuple[Set[str], Set[Tuple[str, str]]]


def _powerset(xs: Iterable[str]):
    xs = list(xs)
    return chain.from_iterable(combinations(xs, r) for r in range(len(xs) + 1))


def defends(af: Framework, s: Set[str], a: str) -> bool:
    for b in {x for (x, y) in af[1] if y == a}:
        if not any((c in s and (c, b) in af[1]) for c in af[0]):
            return False
    return True


def F(af: Framework, s: Set[str]) -> Set[str]:
    return {a for a in af[0] if defends(af, s, a)}


def conflict_free(af: Framework, s: Set[str]) -> bool:
    return not any((a in s and b in s) for (a, b) in af[1])


def admissible(af: Framework, s: Set[str]) -> bool:
    return conflict_free(af, s) and all(defends(af, s, a) for a in s)


def complete_by_def(af: Framework, s: Set[str]) -> bool:
    return admissible(af, s) and F(af, s) <= s


if __name__ == "__main__":
    # Verify: complete  <=>  conflict-free AND F(S) == S, over ALL subsets.
    af: Framework = ({"a", "b", "c"}, {("a", "b"), ("b", "c"), ("c", "a")})
    for t in _powerset(af[0]):
        s = set(t)
        lhs = complete_by_def(af, s)
        rhs = conflict_free(af, s) and F(af, s) == s
        assert lhs == rhs, (s, lhs, rhs)
    print("characterization verified: complete iff conflict-free fixed point of F")

