from typing import Set, Tuple

Framework = Tuple[Set[str], Set[Tuple[str, str]]]


def defense_operator(af: Framework, s: Set[str]) -> Set[str]:
    """F(S): all arguments defended by S (every attacker is counter-attacked)."""
    arguments, attacks = af
    defended: Set[str] = set()
    for a in arguments:
        atkers = {x for (x, y) in attacks if y == a}
        if all(any((c in s and (c, b) in attacks) for c in arguments) for b in atkers):
            defended.add(a)
    return defended


def grounded_extension(af: Framework) -> Set[str]:
    """Least fixed point of F, reached by monotone iteration from the empty set.

    Complexity: at most |A| iterations (the chain strictly grows until it
    stabilizes), each computing F in O(|A| * |R|) time, for O(|A|^2 * |R|)
    overall -- polynomial in the size of the framework.
    """
    current: Set[str] = set()
    while True:
        nxt = defense_operator(af, current)
        if nxt == current:
            return current
        current = nxt

