from typing import Set, Tuple

Framework = Tuple[Set[str], Set[Tuple[str, str]]]


def defense_operator(af: Framework, s: Set[str]) -> Set[str]:
    arguments, attacks = af
    return {a for a in arguments
            if all(any((c in s and (c, b) in attacks) for c in arguments)
                   for b in {x for (x, y) in attacks if y == a})}


def is_conflict_free(af: Framework, s: Set[str]) -> bool:
    return not any((a in s and b in s) for (a, b) in af[1])


def is_complete(af: Framework, s: Set[str]) -> bool:
    """A set is complete iff it is a conflict-free fixed point of F.

    This is the fixed-point criterion: test conflict-freeness in O(|R|) and the
    equation F(S) = S in O(|A| * |R|), giving an O(|A| * |R|) membership test.
    """
    return is_conflict_free(af, s) and defense_operator(af, s) == s

