"""Draw an argumentation framework and highlight its grounded extension."""
import matplotlib.pyplot as plt
from matplotlib.patches import FancyArrowPatch, Circle
import math
from typing import Dict, Set, Tuple

Framework = Tuple[Set[str], Set[Tuple[str, str]]]


def defends(af, s, a):
    for b in {x for (x, y) in af[1] if y == a}:
        if not any((c in s and (c, b) in af[1]) for c in af[0]):
            return False
    return True


def grounded(af: Framework) -> Set[str]:
    cur: Set[str] = set()
    while True:
        nxt = {a for a in af[0] if defends(af, cur, a)}
        if nxt == cur:
            return cur
        cur = nxt


def draw(af: Framework, title: str) -> None:
    nodes = sorted(af[0])
    n = len(nodes)
    pos = {v: (math.cos(2 * math.pi * i / n), math.sin(2 * math.pi * i / n))
           for i, v in enumerate(nodes)}
    g = grounded(af)
    fig, ax = plt.subplots(figsize=(6, 6))
    for (a, b) in af[1]:
        ax.add_patch(FancyArrowPatch(pos[a], pos[b], arrowstyle="-|>",
                                     mutation_scale=20, shrinkA=18, shrinkB=18,
                                     color="#c0392b", lw=1.6))
    for v in nodes:
        col = "#2ecc71" if v in g else "#ecf0f1"
        ax.add_patch(Circle(pos[v], 0.16, facecolor=col, edgecolor="#2c3e50", lw=2, zorder=3))
        ax.text(*pos[v], v, ha="center", va="center", fontsize=14, zorder=4)
    ax.set_xlim(-1.5, 1.5); ax.set_ylim(-1.5, 1.5)
    ax.set_aspect("equal"); ax.axis("off")
    ax.set_title(f"{title}\ngrounded extension = {{{', '.join(sorted(g)) or ' '}}}")
    plt.tight_layout(); plt.show()


if __name__ == "__main__":
    draw(({"a", "b", "c"}, {("a", "b"), ("b", "c")}), "Chain a -> b -> c")
    draw(({"a", "b"}, {("a", "b"), ("b", "a")}), "2-cycle a <-> b")

"""Plot the size of the defense-operator iterates converging to the grounded extension."""
import matplotlib.pyplot as plt
from typing import List, Set, Tuple

Framework = Tuple[Set[str], Set[Tuple[str, str]]]


def defends(af, s, a):
    for b in {x for (x, y) in af[1] if y == a}:
        if not any((c in s and (c, b) in af[1]) for c in af[0]):
            return False
    return True


def trace(af: Framework) -> List[Set[str]]:
    ts = [set()]
    while True:
        nxt = {a for a in af[0] if defends(af, ts[-1], a)}
        if nxt == ts[-1]:
            return ts
        ts.append(nxt)


def build_long_chain(n: int) -> Framework:
    # x0 -> x1 -> ... -> x_{n-1}: grounded accepts every even-indexed argument.
    xs = [f"x{i}" for i in range(n)]
    atk = {(xs[i], xs[i + 1]) for i in range(n - 1)}
    return (set(xs), atk)


if __name__ == "__main__":
    fig, ax = plt.subplots(figsize=(7, 4.5))
    for n in (5, 9, 13):
        ts = trace(build_long_chain(n))
        ax.plot(range(len(ts)), [len(t) for t in ts], marker="o",
                label=f"chain length {n}")
    ax.set_xlabel("iteration k of the defense operator")
    ax.set_ylabel("|F^k(emptyset)|")
    ax.set_title("Monotone convergence to the grounded extension")
    ax.legend(); ax.grid(alpha=0.3)
    plt.tight_layout(); plt.show()

"""Visualize the subset lattice, marking complete extensions and the grounded (least) one."""
import matplotlib.pyplot as plt
from itertools import chain, combinations
from typing import Iterable, List, Set, Tuple

Framework = Tuple[Set[str], Set[Tuple[str, str]]]


def powerset(xs: Iterable[str]):
    xs = list(xs)
    return [frozenset(c) for r in range(len(xs) + 1) for c in combinations(xs, r)]


def defends(af, s, a):
    for b in {x for (x, y) in af[1] if y == a}:
        if not any((c in s and (c, b) in af[1]) for c in af[0]):
            return False
    return True


def F(af, s): return {a for a in af[0] if defends(af, s, a)}
def cf(af, s): return not any((a in s and b in s) for (a, b) in af[1])
def complete(af, s): return cf(af, set(s)) and F(af, set(s)) == set(s)


if __name__ == "__main__":
    af: Framework = ({"a", "b"}, {("a", "b"), ("b", "a")})  # 2-cycle
    sets = sorted(powerset(af[0]), key=lambda s: (len(s), sorted(s)))
    levels = {}
    for s in sets:
        levels.setdefault(len(s), []).append(s)
    fig, ax = plt.subplots(figsize=(6, 6))
    coords = {}
    for lvl, members in levels.items():
        for i, s in enumerate(members):
            x = i - (len(members) - 1) / 2
            coords[s] = (x, lvl)
    # Hasse edges (cover relation)
    for s in sets:
        for t in sets:
            if s < t and len(t) == len(s) + 1:
                ax.plot([coords[s][0], coords[t][0]], [coords[s][1], coords[t][1]],
                        color="#bdc3c7", zorder=1)
    for s in sets:
        is_c = complete(af, s)
        is_g = is_c and all(s <= c for c in sets if complete(af, c))
        col = "#e74c3c" if is_g else ("#3498db" if is_c else "#ecf0f1")
        ax.scatter(*coords[s], s=1400, c=col, edgecolors="#2c3e50", zorder=2)
        label = "{" + ",".join(sorted(s)) + "}" if s else "{}"
        ax.text(*coords[s], label, ha="center", va="center", fontsize=10, zorder=3)
    ax.set_title("Subset lattice of {a,b} for the 2-cycle\n"
                 "red = grounded (least complete), blue = other complete extensions")
    ax.axis("off"); plt.tight_layout(); plt.show()
